using Azurite.NormalEditor.Entry;
using System.Text.Json;

var checks=new List<object>();
void Test(string name,Action body){try{body();checks.Add(new{name,passed=true,error=(string?)null});}catch(Exception e){checks.Add(new{name,passed=false,error=e.ToString()});}}
void Need(bool value,string why){if(!value)throw new Exception(why);}

Test("natural Start return and finalizer followed by later idle tick emits one ready record",()=>{
 var f=new Fixture();f.Start();f.Tick();Need(f.Gate.Ready&&f.Gate.Failure is null,"not ready");Need(f.IdleCalls==1,"guard not called exactly once");Need(f.Events.Select(e=>e.Kind).SequenceEqual(new[]{"catalog-start-enter","catalog-start-return","catalog-start-complete","catalog-ready"}),"authentic lifecycle missing");var e=f.Events.Last();Need(e.Sequence==4&&e.Stamp.CatalogOwner==100&&e.Observation!.WorkbenchOwner==200&&e.Observation.SettingsOwner==300&&e.Observation.ResourceOwner==400,"evidence lost actual owners");
});
Test("same frame cannot qualify; a later native frame can",()=>{var f=new Fixture();f.Start();f.Tick(f.Observation with{Stamp=f.Stamp(10,4)});Need(!f.Gate.Ready&&f.IdleCalls==0,"same-frame readiness");f.Tick();Need(f.Gate.Ready,"later tick rejected");});
Test("workbench updates before Catalog Start wait without inventing readiness",()=>{var f=new Fixture();f.Tick(f.Observation with{Stamp=f.Stamp(1,1,0)});Need(!f.Gate.Ready&&f.IdleCalls==0&&f.Gate.Failure is null,"natural early update failed");f.Start();f.Tick();Need(f.Gate.Ready,"subsequent natural Start failed");});
Test("return without matching prefix cannot qualify",()=>{var f=new Fixture();f.Gate.StartReturned(null,f.Stamp(10,2),true);f.Tick();Need(f.Gate.Failure is not null&&!f.Gate.Ready&&f.IdleCalls==0,"foreign completion accepted");});
Test("postfix alone is not natural completion",()=>{var f=new Fixture();var frame=f.Gate.StartEntered(f.Stamp(10,1));f.Gate.StartReturned(frame,f.Stamp(10,2),true);f.Tick();Need(!f.Gate.Ready&&f.IdleCalls==0,"finalizer skipped");});
Test("skipped native Start refuses readiness",()=>{var f=new Fixture();var frame=f.Gate.StartEntered(f.Stamp(10,1));f.Gate.StartReturned(frame,f.Stamp(10,2),false);f.Gate.StartFinalized(frame,f.Stamp(10,3),null);f.Tick();Need(f.Gate.Failure is not null&&!f.Gate.Ready,"suppressed original accepted");});
Test("original exception is preserved and blocks ready",()=>{var f=new Fixture();var frame=f.Gate.StartEntered(f.Stamp(10,1));var error=new InvalidOperationException("native-start-failed");var returned=f.Gate.StartFinalized(frame,f.Stamp(10,2),error);f.Tick();Need(ReferenceEquals(error,returned)&&f.Gate.Failure!.Contains("native-start-failed")&&!f.Gate.Ready,"native exception changed");});
Test("finalizer before original return refuses",()=>{var f=new Fixture();var frame=f.Gate.StartEntered(f.Stamp(10,1));f.Gate.StartFinalized(frame,f.Stamp(10,2),null);f.Tick();Need(f.Gate.Failure is not null&&!f.Gate.Ready,"missing postfix accepted");});
Test("foreign issued start token refuses",()=>{var f=new Fixture();var other=new Fixture();var token=other.Gate.StartEntered(other.Stamp(10,1));f.Gate.StartEntered(f.Stamp(10,1));f.Gate.StartReturned(token,f.Stamp(10,2),true);Need(f.Gate.Failure is not null,"foreign token accepted");});
Test("duplicate start refuses even for same owner",()=>{var f=new Fixture();f.Gate.StartEntered(f.Stamp(10,1));f.Gate.StartEntered(f.Stamp(10,2));f.Tick();Need(f.Gate.Failure is not null&&!f.Gate.Ready,"duplicate Start accepted");});
Test("duplicate original return refuses",()=>{var f=new Fixture();var token=f.Gate.StartEntered(f.Stamp(10,1));f.Gate.StartReturned(token,f.Stamp(10,2),true);f.Gate.StartReturned(token,f.Stamp(10,3),true);Need(f.Gate.Failure is not null,"duplicate return accepted");});
Test("duplicate finalizer refuses",()=>{var f=new Fixture();var token=f.Start();f.Gate.StartFinalized(token,f.Stamp(10,4),null);Need(f.Gate.Failure is not null&&!f.Gate.Ready,"duplicate finalizer accepted");});
Test("later ticks never repeat ready evidence or guard call",()=>{var f=new Fixture();f.Start();f.Tick();f.Tick(f.Observation with{Stamp=f.Stamp(12,8)});Need(f.Events.Count(e=>e.Kind=="catalog-ready")==1&&f.IdleCalls==1,"duplicate ready output");});
foreach(var field in new[]{"run","process","managed-thread","native-thread","catalog-owner"})Test("reject mismatched "+field+" at tick",()=>{var f=new Fixture();f.Start();var stamp=f.Stamp(11,5);stamp=field switch{"run"=>stamp with{RunId="11111111-1111-1111-1111-111111111111"},"process"=>stamp with{ProcessId=43},"managed-thread"=>stamp with{ManagedThreadId=9},"native-thread"=>stamp with{NativeThreadId=99},_=>stamp with{CatalogOwner=101}};f.Tick(f.Observation with{Stamp=stamp});Need(f.Gate.Failure is not null&&!f.Gate.Ready&&f.IdleCalls==0,"cross context accepted");});
foreach(var flag in new[]{"settings","resources","preloading","loading","current","opening","scene","cli","transport","settings-missing","resources-missing","workbench-missing"})Test("not ready while "+flag,()=>{var f=new Fixture();f.Start();var o=f.Observation;o=flag switch{"settings"=>o with{SettingsReady=false},"resources"=>o with{ResourcesReady=false},"preloading"=>o with{Preloading=true},"loading"=>o with{LoadingCount=1},"current"=>o with{CurrentSession=800},"opening"=>o with{ControlOpening=true},"scene"=>o with{Scene="Loading"},"cli"=>o with{CliActive=true},"transport"=>o with{TransportPresent=true},"settings-missing"=>o with{SettingsOwner=0},"resources-missing"=>o with{ResourceOwner=0},_=>o with{WorkbenchOwner=0}};f.Tick(o);Need(!f.Gate.Ready&&f.IdleCalls==0,"guard called without prerequisite");});
Test("waiting resumes only when genuine observations become ready",()=>{var f=new Fixture();f.Start();f.Tick(f.Observation with{SettingsReady=false});f.Tick(f.Observation with{Stamp=f.Stamp(12,6)});Need(f.Gate.Ready&&f.IdleCalls==1,"pending state did not observe readiness");});
foreach(var owner in new[]{"workbench","settings","resource"})Test("owner replacement while waiting is rejected: "+owner,()=>{var f=new Fixture();f.Start();f.Tick(f.Observation with{SettingsReady=false});var o=f.Observation with{Stamp=f.Stamp(12,6)};o=owner switch{"workbench"=>o with{WorkbenchOwner=201},"settings"=>o with{SettingsOwner=301},_=>o with{ResourceOwner=401}};f.Tick(o);Need(f.Gate.Failure is not null&&f.IdleCalls==0,"owner silently rebound");});
Test("native idle guard failure is final and cannot be retried",()=>{var f=new Fixture();f.Start();f.Gate.Tick(f.Observation,()=>{f.IdleCalls++;throw new Exception("EDITOR_BUSY");});f.Tick(f.Observation with{Stamp=f.Stamp(12,6)});Need(f.Gate.Failure!.Contains("EDITOR_BUSY")&&f.IdleCalls==1&&!f.Gate.Ready,"guard failure retried or hidden");});
Test("readiness drift across native idle check refuses",()=>{var f=new Fixture();f.Start();f.Gate.Tick(f.Observation,()=>f.Observation with{CurrentSession=900});Need(!f.Gate.Ready&&f.Gate.Failure is not null,"guard-to-read drift accepted");});
Test("idle check readback from another frame refuses",()=>{var f=new Fixture();f.Start();f.Gate.Tick(f.Observation,()=>f.Observation with{Stamp=f.Stamp(12,6)});Need(!f.Gate.Ready&&f.Gate.Failure is not null,"cross-frame guard result accepted");});
Test("same frame stable readback may consume monotonic time",()=>{var f=new Fixture();f.Start();f.Gate.Tick(f.Observation,()=>f.Observation with{Stamp=f.Stamp(11,6)});Need(f.Gate.Ready&&f.Gate.Failure is null,"real clock advance rejected");});
Test("idle check exceeding deadline cannot qualify",()=>{var f=new Fixture();f.Start();f.Gate.Tick(f.Observation,()=>f.Observation with{Stamp=f.Stamp(11,101)});Need(!f.Gate.Ready&&f.Gate.Failure is not null,"late guard completion accepted");});
Test("reentrant readiness check cannot produce duplicate acceptance",()=>{var f=new Fixture();f.Start();f.Gate.Tick(f.Observation,()=>{f.Tick();return f.Observation;});Need(!f.Gate.Ready&&f.Gate.Failure is not null&&f.Events.All(e=>e.Kind!="catalog-ready"),"reentrant guard produced ready");});
Test("deadline before Catalog Start fails rather than passing",()=>{var f=new Fixture();f.Tick(f.Observation with{Stamp=f.Stamp(100,101,0)});Need(f.Gate.Failure is not null&&!f.Gate.Ready,"missing start timeout ignored");});
Test("deadline while native readiness remains false fails",()=>{var f=new Fixture();f.Start();f.Tick(f.Observation with{SettingsReady=false,Stamp=f.Stamp(100,101)});Need(f.Gate.Failure is not null&&!f.Gate.Ready,"waiting timeout ignored");});
Test("late original completion fails",()=>{var f=new Fixture();var token=f.Gate.StartEntered(f.Stamp(10,1));f.Gate.StartReturned(token,f.Stamp(10,101),true);Need(f.Gate.Failure is not null&&!f.Gate.Ready,"late return accepted");});
Test("clock reversal fails",()=>{var f=new Fixture();f.Start();f.Tick(f.Observation with{Stamp=f.Stamp(11,2)});Need(f.Gate.Failure is not null,"clock reversed");});
Test("sink failure cannot leave accepted readiness",()=>{var events=new List<CatalogEvidence>();var gate=new CatalogReadiness(Fixture.Binding,e=>{events.Add(e);if(e.Kind=="catalog-ready")throw new IOException("sink failed");});var f=new Fixture(gate,events);f.Start();f.Tick();Need(!gate.Ready&&gate.Failure!.Contains("sink failed"),"lost durable evidence accepted");});
Test("ready sink rejection cannot revive accepted readiness",()=>{var events=new List<CatalogEvidence>();CatalogReadiness? gate=null;gate=new(Fixture.Binding,e=>{events.Add(e);if(e.Kind=="catalog-ready")gate!.Reject("sink rejected run",e.Stamp);});var f=new Fixture(gate,events);f.Start();f.Tick();Need(!gate.Ready&&gate.Failure=="sink rejected run","ready emission revived failed run");});
Test("ready sink reentry cannot duplicate guard or acceptance",()=>{var events=new List<CatalogEvidence>();Fixture? f=null;var attempted=false;var gate=new CatalogReadiness(Fixture.Binding,e=>{events.Add(e);if(e.Kind=="catalog-ready"&&!attempted){attempted=true;f!.Tick();}});f=new(gate,events);f.Start();f.Tick();Need(!gate.Ready&&gate.Failure is not null&&f.IdleCalls==1&&events.Count(e=>e.Kind=="catalog-ready")==1,"evidence sink reentry produced duplicate readiness");});
Test("lifecycle evidence cannot reenter native completion observation",()=>{var events=new List<CatalogEvidence>();CatalogReadiness? gate=null;CatalogStartFrame? token=null;gate=new(Fixture.Binding,e=>{events.Add(e);if(e.Kind=="catalog-start-return")gate!.StartFinalized(token,e.Stamp,null);});var f=new Fixture(gate,events);token=gate.StartEntered(f.Stamp(10,1));gate.StartReturned(token,f.Stamp(10,2),true);f.Tick();Need(!gate.Ready&&gate.Failure is not null&&f.IdleCalls==0&&events.All(e=>e.Kind!="catalog-start-complete"),"sink manufactured native completion");});
Test("failure reason is preserved after late callbacks",()=>{var f=new Fixture();f.Gate.Reject("first failure",f.Stamp(1,1));f.Gate.Reject("later failure",f.Stamp(1,2));Need(f.Gate.Failure=="first failure"&&f.Events.Count(e=>e.Kind=="catalog-failed")==1,"primary failure overwritten");});

TickCallbackChecks.Run(Test,Need);
ObservationBridgeChecks.Run(Test,Need);
ClockAnchorChecks.Run(Test,Need);
if(args.Length==2)MetadataChecks.Run(args[0],args[1],Test,Need);
var json=JsonSerializer.Serialize(checks);Console.WriteLine(json);var failed=checks.Count(x=>!(bool)x.GetType().GetProperty("passed")!.GetValue(x)!);Console.WriteLine($"RESULT passed={checks.Count-failed} failed={failed}; nativeExecuted=false; hostExecuted=false");return failed==0?0:1;

sealed class Fixture
{
 internal static CatalogBinding Binding=>new("01234567-89ab-cdef-0123-456789abcdef",42,7,8,100);
 internal readonly List<CatalogEvidence> Events;
 internal readonly CatalogReadiness Gate;
 internal int IdleCalls;
 internal Fixture(){Events=new();Gate=new(Binding,Events.Add);}
 internal Fixture(CatalogReadiness gate,List<CatalogEvidence> events){Gate=gate;Events=events;}
 internal CatalogStamp Stamp(long frame,long milliseconds,long owner=100)=>new(Binding.RunId,42,7,8,frame,milliseconds,owner);
 internal CatalogObservation Observation=>new(Stamp(11,5),200,300,400,"CatalogScene",false,false,true,true,false,0,0,false);
 internal CatalogStartFrame? Start(){var token=Gate.StartEntered(Stamp(10,1));Gate.StartReturned(token,Stamp(10,2),true);Gate.StartFinalized(token,Stamp(10,3),null);return token;}
 internal void Tick(CatalogObservation? o=null){var snapshot=o??Observation;Gate.Tick(snapshot,()=>{IdleCalls++;return snapshot;});}
}
